import { allocateInteger, resourceQuanta } from './planetary-data-generator.js';
import { resourceRandom as rng, assignGradeJitter, weightedGradeMean } from './ore-quality.js';
import { PROCEDURAL_RESOURCE_PARAMETERS as tuning, SOL_RESOURCE_SETTINGS } from './body-resource-profiles.js';
import { surfaceTypeFor } from './planetary-surface-model.js';
import { validateResourceConfiguration } from './resource-contract.js';
const p=(low,high)=>({low,medium:1-low-high,high});
const hash=(...k)=>Math.floor(rng(...k)*2**32).toString(16);
const round=n=>Math.round(n*1000)/1000;
export function canonicalResourceConfiguration(systemId,body,worldSeed=`${systemId}:${body.id}:resources:v1`){return {worldSeed,...(systemId==='sol'?structuredClone(SOL_RESOURCE_SETTINGS[body.id]??{}):{})};}
function proceduralConfiguration(body,seed){const atmosphere=surfaceTypeFor(body)==='atmosphere',radius=body.realRadiusKm??6371*(body.planetSize??15)/15,richness=tuning.minimumRichness+rng(seed,'ore','richness')*(tuning.maximumRichness-tuning.minimumRichness),totalOreU=atmosphere||rng(seed,'ore','absence')<tuning.absenceProbability?0:round(Math.min(1e12,tuning.baseOreU*(Math.max(1,radius)/6371)**1.5*richness)),raw={surface:.3+rng(seed,'shares','surface')*.7,vein:.1+rng(seed,'shares','vein')*.4,deep:.1+rng(seed,'shares','deep')*.5},sum=Object.values(raw).reduce((a,b)=>a+b,0);return {totalOreU,typeShares:Object.fromEntries(Object.entries(raw).map(([k,v])=>[k,v/sum])),gradeTargets:{surface:p(.25+rng(seed,'quality','surface-low')*.55,.01+rng(seed,'quality','surface-high')*.15),vein:p(.1+rng(seed,'quality','vein-low')*.4,.1+rng(seed,'quality','vein-high')*.3),deep:p(.03+rng(seed,'quality','deep-low')*.15,.25+rng(seed,'quality','deep-high')*.5)}};}
function connectedGroups(grid,tiles,seed){const unused=new Set(tiles.map(t=>t.id)),groups=[],count=Math.min(tiles.length,1+Math.floor(rng(seed,'vein-count')*5));for(let g=0;g<count&&unused.size;g++){const candidates=[...unused].sort((a,b)=>rng(seed,g,a)-rng(seed,g,b)),root=candidates[0],ids=[root],frontier=new Set(grid.byId.get(root).neighborIds.filter(id=>unused.has(id)));unused.delete(root);const length=Math.max(2,Math.round(tiles.length*(.025+rng(seed,g,'length')*.12)));while(ids.length<length&&frontier.size){const id=[...frontier].sort((a,b)=>rng(seed,g,ids.length,a)-rng(seed,g,ids.length,b))[0];frontier.delete(id);if(!unused.has(id))continue;unused.delete(id);ids.push(id);for(const n of grid.byId.get(id).neighborIds)if(unused.has(n))frontier.add(n);}groups.push(ids);}return groups;}
export function generateBodyResources({systemId,body,grid,worldSeed='world-v1',policy='proceduralBudget',settings={},tileIds=null,budgetsByKind=null,weightsByTile={},landFractionsByTile={}}){
 if(grid.systemId!==systemId||grid.bodyId!==body.id)throw Error('자원 생성 대상 격자 불일치');if(typeof worldSeed!=='string'||worldSeed.length>200)throw Error('시드 문자열 범위');if(!['fixedBudget','proceduralBudget'].includes(policy))throw Error('예산 모드 오류');
 if(settings.generatorVersion!==undefined&&settings.generatorVersion!==1)throw Error('지원하지 않는 자원 생성기 버전');
 const bodySeed=`${worldSeed}/${systemId}/${body.id}/resources-v1`,base=proceduralConfiguration(body,bodySeed),config={...base,jitter:tuning.jitter,certainty:'provisional',notes:'잠정 게임 밸런스 · 천문 관측 매장량 아님',...structuredClone(settings),generatorVersion:1,worldSeed,budgetPolicy:policy==='fixedBudget'?'fixed':'procedural'};
 const ids=[...(tileIds??grid.tiles.map(t=>t.id))].sort((a,b)=>a<b?-1:a>b?1:0);if(new Set(ids).size!==ids.length||ids.some(id=>!grid.byId.has(id)))throw Error('자원 생성 셀 범위 오류');const tiles=ids.map(id=>grid.byId.get(id)),cells=Object.fromEntries(ids.map(id=>[id,[]]));
 if(config.totalOreU===null)return {configuration:null,cells:Object.fromEntries(ids.map(id=>[id,null])),hydrogenSources:[],seed:bodySeed};
 validateResourceConfiguration(config);if(Object.keys(config.typeShares).some(k=>!['surface','vein','deep'].includes(k)&&config.typeShares[k]>0))throw Error('추가 매장 형태의 생성 알고리즘을 먼저 등록해야 합니다.');if(surfaceTypeFor(body)==='atmosphere'&&config.totalOreU>0)throw Error('대기 기준층 ore 금지');
 const typeQuanta=budgetsByKind??Object.fromEntries(allocateInteger(resourceQuanta(config.totalOreU),Object.entries(config.typeShares).map(([id,weight])=>({id,weight}))));
 const namespace=(systemId+'-'+body.id).replace(/[^A-Za-z0-9_.-]/g,'_').slice(0,35)+'-'+hash(systemId,body.id,bodySeed,...ids);
 for(const kind of ['surface','vein','deep']){const total=typeQuanta[kind];if(!Number.isSafeInteger(total)||total<0)throw Error('형태별 정수 예산 오류');if(!total)continue;if(!tiles.length)throw Error('남은 예산을 배분할 미설정 셀이 없습니다.');
  let groups;if(kind==='surface')groups=[tiles.map(t=>t.id)];else if(kind==='vein'){const preferred=config.placementPolicy?tiles.filter(t=>typeof landFractionsByTile[t.id]==='number'&&landFractionsByTile[t.id]>=config.placementPolicy.veinPreferredLandThreshold):tiles;if(config.placementPolicy&&!preferred.length)throw Error('육지·대륙붕 광맥 후보/육해 데이터가 없습니다.');groups=connectedGroups(grid,preferred,bodySeed);}else groups=[tiles.filter(t=>rng(bodySeed,'deep-site',t.id)<.45).map(t=>t.id)];if(!groups.flat().length)groups=[[tiles[0].id]];
  const positions=groups.flatMap((members,g)=>members.map(id=>{const t=grid.byId.get(id),noise=Math.sin(t.center.x*4+rng(bodySeed,kind,'phase')*6)+Math.cos(t.center.y*3-t.center.z*2),weight=t.areaWeight*(.15+Math.exp(noise))*(weightsByTile[id]??1)*(.5+rng(bodySeed,kind,g,id));return {id,weight,g};})),shares=allocateInteger(total,positions);
  const list=[];for(const row of positions){const q=shares.get(row.id);if(!q)continue;const tile=grid.byId.get(row.id),extractionFloor=settings.extractionFloor??0,processingFloor=settings.processingFloor??0,d={depositId:`r1-${namespace}-${kind}-${tile.index}-${row.g}`,groupId:`g1-${namespace}-${kind}-${row.g}`,resourceId:'ore',depositKind:kind,initialReserveU:q/1000,gradeProbabilities:{...config.gradeTargets[kind]},extractionDifficulty:round(Math.max(extractionFloor,(kind==='deep'?60:kind==='vein'?30:10)+rng(bodySeed,kind,row.id,'extraction')*25)),processingDifficulty:round(Math.max(processingFloor,15+rng(bodySeed,row.id,'processing')*55)),discoveryTier:kind==='surface'?Math.floor(rng(bodySeed,row.id,'detect')*2):kind==='vein'?1+Math.floor(rng(bodySeed,row.id,'detect')*2):3+Math.floor(rng(bodySeed,row.id,'detect')*3),accessDepth:kind==='deep'?round(50+rng(bodySeed,row.id,'depth')*50):kind==='vein'?round(5+rng(bodySeed,row.id,'depth')*30):0,compositionTags:[],notes:config.notes};const placement=config.placementPolicy;if(kind==='surface'&&placement&&typeof landFractionsByTile[row.id]==='number'&&1-landFractionsByTile[row.id]>=placement.oceanSurfaceWaterThreshold){d.extractionDifficulty=Math.max(d.extractionDifficulty,placement.oceanExtractionFloor);d.discoveryTier=Math.max(d.discoveryTier,placement.oceanDiscoveryTierMin);d.notes+=' · 해양 표면형: 해저 단괴';}if(kind==='vein'&&placement)d.notes+=' · 육지/대륙붕(육해혼합 근사) 우선';cells[row.id].push(d);list.push(d);}
  assignGradeJitter(list,config.gradeTargets[kind],{seed:[bodySeed,kind],strength:config.jitter});
 }
 const hydrogenSources=[];if(surfaceTypeFor(body)==='atmosphere'||body.geologyProfileId==='ice-surface'||body.geologyProfileId==='terrestrial-earthlike'){const atmospheric=surfaceTypeFor(body)==='atmosphere';for(let i=0;i<Math.min(atmospheric?3:2,grid.cellCount);i++){const tile=grid.tiles[Math.floor(rng(bodySeed,'hydrogen-location',i)*grid.cellCount)];hydrogenSources.push({sourceId:`h1-${namespace}-${i}`,tileId:tile.id,resourceId:'hydrogen',sourceType:atmospheric?'atmospheric-collector':'finite-source',initialReserveU:atmospheric?null:round(1e7*(.25+rng(bodySeed,'hydrogen-richness',i)*3)),potentialCollectionUPerCycle:null,operatingDifficulty:round(30+rng(bodySeed,'hydrogen-difficulty',i)*60),facilityRequirement:atmospheric?'atmospheric-collector':'ice-water-extraction',notes:'잠정 잠재 공급원. 정제 수율·생산·유지비 미구현, 시작 재고 아님'});}}
 return {configuration:config,cells,hydrogenSources,seed:bodySeed};
}
